import json,pathlib,collections
r=pathlib.Path(__file__).resolve().parents[1];profile=json.loads((r/'spec/requested-profile.json').read_text());features=json.loads((r/'spec/feature-matrix.json').read_text());cases=json.loads((r/'tests/fixtures/manifest.json').read_text())['cases']
notes={}
def group(ids,status,modules,note):
 for slug in ids.split():notes[slug]=(status,modules.split(),note)
group('css-background-color css-background-origin css-background-position css-background-repeat css-background-size css-background-clip css-background-image css-background css-linear-gradient','partial','src/style.rs src/layout.rs src/resources.rs src/paint.rs','Common color/raster backgrounds, typed linear gradients, clipping, sizing and tiling exist. Layer-specific position/size lists, shorthand completeness, color/raster precision and gradient edge cases remain.')
group('css-width css-height css-min-width css-min-height css-max-width css-max-height css-inline-size css-block-inline-size css-max-inline-size css-min-inline-size css-box-sizing css-unit-percent css-unit-px css-unit-cm css-unit-em css-unit-in css-unit-mm css-unit-pc css-unit-pt css-unit-rem css-unit-vh css-unit-vw css-unit-calc','implemented','src/core.rs src/style.rs src/layout.rs','Bounded fixed-point lengths, affine calc, min/max dimensions and horizontal logical aliases. This denotes executable coverage, not full CSS standards conformance; percentage-height and formatting-context interactions need broader coverage.')
group('css-unit-ch css-unit-ex','partial','src/style.rs src/layout.rs','Recognized but currently approximated using half the font size; actual font metrics are needed.')
group('css-unit-initial','implemented','src/style.rs','CSS-wide initial/inherit/unset copies for supported longhands; supported shorthands expand those values. Values participating in relative font-size resolution are handled before geometry.')
group('css-border css-border-radius','partial','src/style.rs src/layout.rs src/paint.rs','Border styles use WebRender normal borders; uniform absolute/percentage rounding exists. Multiple/elliptical corner radii and some border rasterization remain incomplete.')
group('css-border-collapse css-border-spacing css-table-layout css-caption-side css-vertical-align','partial','src/layout.rs','Bounded automatic/fixed tables, spans, captions, spacing and cell alignment. Common solid collapsed borders work; row/column-group conflicts, odd-width joins, complete baseline alignment and anonymous table roles need work.')
group('css-empty-cells','implemented','src/style.rs src/layout.rs','Empty cell background/border suppression preserves table geometry; nonempty text/replaced content remains painted. Complex row/group backgrounds still follow table limitations.')
group('css-display css-display-none css-clear css-float css-overflow','partial','src/style.rs src/layout.rs','Implemented static block/inline/inline-block/table roles, floats, clear and clipping, including block descendants inside inline wrappers. Full formatting contexts, inline box edges, nested overflow and some reflow interactions need work.')
group('css-margin css-margin-block-start-end css-margin-inline-block css-margin-inline-start-end css-padding css-padding-block-start-end css-padding-inline-block css-padding-inline-start-end','implemented','src/style.rs src/layout.rs','Finite signed margins, nonnegative padding and horizontal logical aliases. Margin-collapse behavior is covered by targeted fixtures but not exhaustive browser tests.')
group('css-font css-font-weight css-font-size css-font-kerning css-sytem-ui','partial','src/style.rs src/text.rs','Approved OS DejaVu defaults and Liberation aliases for Arial/Helvetica, Times and Courier; bold/italic variants, kerning, size and font shorthand. No downloaded fonts; script/CJK/emoji fallback and platform resolvers are incomplete.')
group('css-letter-spacing css-word-spacing css-line-height css-text-align css-white-space css-overflow-wrap css-word-wrap css-word-break css-text-transform css-text-indent','partial','src/style.rs src/text.rs src/layout.rs','Rust shaping/bidi/line breaking, normal/unitless line height, whitespace and bounded spacing/indentation. Full justification, language-specific transforms, vertical writing and all break behavior remain unproven or incomplete.')
group('css-rgb css-rgba','implemented','src/style.rs src/paint.rs','CSS color parsing into bounded RGBA values; native blending can still differ from Gecko by one channel level.')
group('css-important css-comments css-selector-adjacent-sibling css-selector-chaining css-selector-child css-selector-class css-selector-descendant css-selector-general-sibling css-selector-grouping css-selector-id css-selector-type css-selector-universal css-selector-attribute','implemented','src/css.rs src/style.rs','Bounded static cascade and selector matching with declaration recovery. Unknown properties do not enable capabilities. This is not a formal parser-equivalence proof.')
group('css-at-media','partial','src/css.rs','Bounded screen/all and min/max viewport width conditions, comma alternatives and basic Boolean forms. Arbitrarily nested Boolean query grammar is incomplete.')
group('css-pseudo-class-focus css-pseudo-class-focus-visible css-pseudo-class-hover','integration','src/css.rs src/style.rs','State matching exists through explicit API inputs. The CLI does not deliver interactive state changes or trusted focus UI; application integration is required.')
group('css-outline','partial','src/style.rs src/layout.rs','Bounded author outlines and offsets on ordinary boxes/replaced elements. Inline outline unions, collapsed-table outlines and trusted application focus indication require further work.')
group('css-text-overflow','partial','src/style.rs src/layout.rs','Clip and LTR start/left ellipsis with grapheme-boundary truncation exist; logical readable text is preserved. RTL, centered/right-aligned overflow, atomic-box hit regions and all shaping interactions require further work.')
group('css-text-decoration css-text-decoration-color css-text-decoration-line css-text-decoration-style css-text-underline-position','partial','src/style.rs src/layout.rs','Basic underline/overline/strikeout and decoration colors. Alternate decoration styles, underline-position and skip-ink behavior are incomplete or not painted.')
group('css-list-style css-list-style-position css-list-style-type html-lists','partial','src/style.rs src/layout.rs','Inside/outside markers and bounded counters; native bullet geometry, Roman/alphabetic counter ranges, reversed lists and exact marker line metrics remain incomplete.')
group('css-direction html-dir html-bdi','partial','src/style.rs src/text.rs src/layout.rs','Unicode bidi and explicit ltr/rtl supported; logical text preserved. dir=auto and bdi isolation/fallback need fuller implementation; trusted envelope UI is outside this component.')
group('css-opacity css-visibility html-hidden','partial','src/style.rs src/layout.rs src/paint.rs','Ordinary block/replaced-element opacity and visibility/hidden handling exist. Inline/table group opacity and consistent semantic exposure need more coverage; strict opacity pixels currently differ by one level.')
group('css-object-fit css-object-position html-img','partial','src/layout.rs src/resources.rs','Explicit preauthorized raster resources, data images, intrinsic sizing, fit/position and blocked/alt placeholders. No network fetcher. Upsampling differs from Gecko; complete replaced-element sizing needs more tests.')
group('html-align html-valign html-height html-width html-cellpadding html-cellspacing html-background','partial','src/style.rs src/layout.rs','Common legacy hints work, including inherited table cellpadding. Not every legacy parsing/quirks interaction is reproduced.')
group('html-style html-comments html-doctype','implemented','src/dom.rs src/css.rs','Independent original-byte HTML5ever parsing; scoped inline/embedded CSS, ordinary comments and a fixed standards-oriented layout model. Browser quirks-mode emulation and MSO/VML are intentionally absent.')
group('html-abbr html-acronym html-address html-blockquote html-body html-code html-del html-dfn html-div html-h1-h6 html-hr html-p html-pre html-small html-span html-strike html-strong html-wbr','implemented','src/dom.rs src/style.rs src/layout.rs','Static semantic tags and default styles with block/inline text layout; browser UA styles are not exhaustively reproduced.')
group('html-lang html-semantics html-role html-aria-describedby html-aria-hidden html-aria-label html-aria-labelledby','partial','src/layout.rs src/dom.rs','Logical readable text, scoped labels/descriptions, inherited language and a safe role subset are emitted. Native accessibility-tree integration, selection/copy UI, language-sensitive shaping/fallback and every relationship are not implemented.')
group('html-anchor-links html-mailto-links','integration','src/layout.rs','Untrusted target and per-run hit-region metadata is emitted. Message-local anchor navigation, canonical target display and validated user-gesture action/compose brokers belong to the application and are not implemented here.')
group('html-loading-attribute','implemented','src/resources.rs','Loading attributes grant no authority; only supplied capabilities or allowed literal data are decoded. Lazy decode scheduling is currently eager for already approved images.')
group('html-table','partial','src/dom.rs src/layout.rs src/verified.rs','Independent HTML table repair, bounded grid, spans and nested tables. Occupancy interval updates are verified; the table algorithm as a whole is unverified and retains documented layout gaps.')
group('image-apng image-gif image-webp image-jpg image-png image-base64','partial','src/resources.rs src/verified.rs','Rust raster decode only, static first/default image, strict raster data URI types, size/allocation/work limits and verified descriptor checks. APNG/GIF/WebP composition, color profiles and exact Gecko decoder equivalence need broader fixtures; no animation scheduler.')
rows=[]
for f in features:
 slug=f['slug'];requested=f['decision'] in ['Support','Bounded']
 if requested:
  status,modules,note=notes.get(slug,('missing',[],'No implementation mapping yet; do not infer support from the requested policy.'))
 else:status,modules,note='excluded',[], 'Outside this implementation profile: '+f['decision']+'.'
 linked=[c['name'] for c in cases if slug in c['features']]
 rows.append({'slug':slug,'requested_policy':f['decision'],'status':status,'modules':modules,'fixtures':linked,'notes':note})
missing=[x['slug']for x in rows if x['requested_policy'] in ['Support','Bounded'] and not x['modules']]
assert not missing,missing
counts=collections.Counter(x['status']for x in rows if x['requested_policy']in['Support','Bounded'])
result={'scope':'Requested policy is preserved separately; implemented means executable bounded behavior, not complete standards conformance or formal verification. Fixture coverage is narrow and synthetic.','requested_features':155,'counts':dict(counts),'rows':rows}
(r/'spec/implementation-status.json').write_text(json.dumps(result,indent=2)+'\n')
text='# Implementation status\n\n'+result['scope']+'\n\n'
text+='All 155 requested Support/Bounded entries are mapped below. “Integration” means the renderer emits data or exposes an API, while the surrounding mail application must supply the authorized behavior. Stored properties with incomplete behavior are marked partial or missing. No empirical inbox coverage claim is made.\n\n'
text+='| Feature | Requested | Actual | Evidence / limits |\n| --- | --- | --- | --- |\n'
for x in rows:
 if x['requested_policy']not in['Support','Bounded']:continue
 text+='| `'+x['slug']+'` | '+x['requested_policy']+' | '+x['status']+' | '+x['notes'].replace('|','\\|')+(' Fixtures: '+', '.join('`'+n+'`'for n in x['fixtures'])+'.' if x['fixtures']else' No dedicated pixel fixture.')+' |\n'
(r/'docs/implementation-status.md').write_text(text)
print(json.dumps({'requested':155,'counts':dict(counts)}))
